<?php
namespace Dth\Crm\Filament\Resources\CompanyResource\RelationManagers;
use Filament\Resources\RelationManagers\RelationManager; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions; use Filament\Forms\Components\{Select,TextInput,Toggle}; use Dth\Crm\Models\Contact;
class ContactsRelationManager extends RelationManager {protected static string $relationship='contacts'; public static function getTitle($o,string $p):string{return 'Người liên hệ';} public function form(Schema $s):Schema{return $s->components([TextInput::make('job_title')->label('Chức vụ'),TextInput::make('department')->label('Bộ phận'),Select::make('decision_role')->options(['decision_maker'=>'Người quyết định','influencer'=>'Người ảnh hưởng','technical_contact'=>'Kỹ thuật','billing_contact'=>'Thanh toán','end_user'=>'Người dùng','other'=>'Khác']),Toggle::make('is_primary')->label('Liên hệ chính'),Toggle::make('is_active')->label('Đang hoạt động')->default(true)]);} public function table(Table $t):Table{return $t->columns([TextColumn::make('display_name')->label('Tên'),TextColumn::make('email')->label('Email'),TextColumn::make('phone')->label('Điện thoại'),TextColumn::make('pivot.job_title')->label('Chức vụ'),TextColumn::make('pivot.decision_role')->label('Vai trò')->badge(),TextColumn::make('pivot.is_primary')->label('Chính')->formatStateUsing(fn($state):string=>\Dth\Crm\Support\UiText::get($state?'common.yes':'common.no',$state?'Có':'Không',context:'boolean'))->badge()->color(fn($state):string=>$state?'success':'gray')])->headerActions([Actions\AttachAction::make()->preloadRecordSelect()->form(fn(Actions\AttachAction $a):array=>[$a->getRecordSelect(),TextInput::make('job_title')->label('Chức vụ'),TextInput::make('department')->label('Bộ phận'),Select::make('decision_role')->options(['decision_maker'=>'Người quyết định','influencer'=>'Người ảnh hưởng','technical_contact'=>'Kỹ thuật','billing_contact'=>'Thanh toán','end_user'=>'Người dùng','other'=>'Khác']),Toggle::make('is_primary')->label('Liên hệ chính'),Toggle::make('is_active')->label('Đang hoạt động')->default(true)])])->recordActions([Actions\EditAction::make(),Actions\DetachAction::make()]);}}
